class Course {
  static count = 0;

  static of(name, hours) {
    return new Course(name, hours);
  }

  constructor(name, hours) {
    this.name = name;
    this.hours = hours;
    Course.count += 1;
  }

  get label() {
    return this.name + '(' + this.hours + '시간)';
  }

  get isLong() {
    return this.hours >= 10;
  }

  set hoursText(text) {
    this.hours = Number(text);
  }
}

const a = Course.of('리액트 입문', 8);
const b = Course.of('자바스크립트 기초', 12);

console.log('게터는 괄호 없이 :', a.label, '·', a.isLong);
console.log('긴 강의 :', b.label, '·', b.isLong);

a.hoursText = '15';
console.log('세터로 넣은 뒤 :', a.label, '·', a.isLong);

console.log('정적 값 :', Course.count, '· 인스턴스에는 :', a.count);
console.log('자기 것 :', Object.keys(a));
console.log('JSON 으로 만들면 :', JSON.stringify(a));

