class Course {
  static count = 0;

  static of(name, hours) {
    return new this(name, hours);
  }

  constructor(name, hours) {
    this.name = name;
    this.hours = hours;
    Course.count += 1;
  }

  get label() {
    return this.name + '(' + this.hours + '시간)';
  }

  get isLong() {
    return this.hours >= 10;
  }
}

class Workshop extends Course {
  constructor(name, hours, seats) {
    super(name, hours);
    this.seats = seats;
  }

  get label() {
    return super.label + ' 정원 ' + this.seats + '명';
  }
}

// 이 함수는 그대로 두세요
function report() {
  Course.count = 0;
  const a = Course.of('리액트 입문', 8);
  const b = Course.of('자바스크립트 기초', 12);
  const w = new Workshop('리액트 심화', 4, 12);
  const madeByChild = Workshop.of('임시', 1);
  return a.label + ' / ' + b.label + '=' + b.isLong
    + ' / ' + w.label
    + ' / 만든 개수: ' + Course.count
    + ' / 자식이 만든 것: ' + (madeByChild instanceof Workshop);
}
